import{_ as s,o as t,c as r,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Resellers — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Resellers — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/resellers"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Resellers — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/resellers"}]]},"headers":[],"relativePath":"user-guide/resellers.md","filePath":"user-guide/resellers.md","lastUpdated":1787861406000}'),a={name:"user-guide/resellers.md"};function n(i,e,l,d,c,m){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="resellers-—-user-guide" tabindex="-1">Resellers — User Guide <a class="header-anchor" href="#resellers-—-user-guide" aria-label="Permalink to &quot;Resellers — User Guide&quot;">​</a></h1><h2 id="who-can-use-resellers" tabindex="-1">Who can use Resellers <a class="header-anchor" href="#who-can-use-resellers" aria-label="Permalink to &quot;Who can use Resellers&quot;">​</a></h2><p>Your workspace must have the <strong>Resellers</strong> module installed (requires <strong>Payments</strong> first). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>invite</code> as needed).</p><p>Without <strong>assign</strong>, you only see resellers assigned to you, plus the reseller record linked to your own login (<code>user_id</code>).</p><p>A dedicated <strong>reseller</strong> role exists for invited partner logins. That role can view their own reseller record and their commission entries (when Reseller Payouts is installed) — not create or manage other resellers.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Resellers</strong> from the sidebar under the <strong>Sales</strong> group (when the SPA nav ships; Phase 1 exposes the tenant API).</p><ul><li>Search by name, email, phone, or company name</li><li>Filter by status (Active / Inactive) and assignee, or toggle <strong>My resellers</strong></li><li>KPI cards summarize total, my resellers, unassigned, active, and inactive</li><li>Users with <strong>restore</strong> can filter trash and restore soft-deleted resellers</li><li><strong>Delete permanently</strong> requires <code>resellers.force.delete</code> — not on default admin/manager/staff maps (owner/superadmin)</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Create a reseller with <strong>name</strong> (required)</li><li>Optionally set email, phone, company name, notes, status, commission rate, owner commission rate, and assignee</li><li>Save</li></ol><p>Commission rates are percentages from 0 to 100. They are snapshotted onto commission ledger rows when a linked invoice becomes fully <strong>Paid</strong> (see <a href="/user-guide/reseller-payouts">Reseller Payouts</a>).</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee. The assignee is the workspace “owner” party for the second commission tier (<code>owner_commission_rate</code>).</p><h2 id="detail-sheet" tabindex="-1">Detail sheet <a class="header-anchor" href="#detail-sheet" aria-label="Permalink to &quot;Detail sheet&quot;">​</a></h2><p>Open a reseller from the list to see four tabs:</p><ul><li><strong>Overview</strong> — profile fields, commission rates, assignee, and <strong>profile notes</strong> (the optional notes field on create/edit)</li><li><strong>Notes</strong> — threaded team notes (separate from profile notes). Users with <strong>update</strong> can add notes</li><li><strong>Activity</strong> — domain timeline (created, updated, assigned, note added, login invited, deleted/restored)</li><li><strong>Access</strong> — linked login status and invite-login (requires <strong>invite</strong>)</li></ul><h2 id="invite-login" tabindex="-1">Invite login <a class="header-anchor" href="#invite-login" aria-label="Permalink to &quot;Invite login&quot;">​</a></h2><p>Users with <strong>invite</strong> can invite a <strong>same-workspace</strong> login for a reseller who does not already have <code>user_id</code> set:</p><ol><li>Provide a password (required); email and name default from the reseller record when omitted</li><li>The API creates a tenant user with <strong>only</strong> the <code>reseller</code> role and links it</li><li>Email must be unique in the workspace</li></ol><p>This is intentionally <strong>not</strong> cross-workspace identity — each workspace manages its own reseller logins.</p><h2 id="link-on-invoices" tabindex="-1">Link on invoices <a class="header-anchor" href="#link-on-invoices" aria-label="Permalink to &quot;Link on invoices&quot;">​</a></h2><p>When creating or editing a customer invoice, you may set optional <code>reseller_id</code> if Resellers is installed. Without <strong>assign</strong>, you may only link resellers assigned to you.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><ul><li><strong>Payments</strong> — required install dependency; invoice must reach status <strong>Paid</strong> before commission accrues</li><li><strong>Reseller Payouts</strong> — commission ledger, approve / pay / void workflow</li></ul>',24)])])}const u=s(a,[["render",n]]);export{h as __pageData,u as default};
